source:
source note sys.dataset(fields: [title, subtitle, summary, as_of, status, metric1_label, metric1_value, metric2_label, metric2_value, pick1_title, pick1_body, pick2_title, pick2_body, pick3_title, pick3_body])

copy sim { class: vocabulary, en: "Simulation" }
copy b_code { class: vocabulary, en: "Show code" }
copy b_details { class: vocabulary, en: "Pickup details" }
copy b_back { class: vocabulary, en: "Back" }
copy gist { class: model-copy, en: "A signature was needed, so the parcel is now waiting at the pickup desk." }
copy next { class: model-copy, en: "Bring the code and photo ID to collect." }

state mode { shape: enum[brief, code, pickup], initial: .brief }
event show_code { mode: set(.code) }
event show_pickup { mode: set(.pickup) }
event back { mode: set(.brief) }

view root Surface(pad: .tight) {
  Col(gap: 8) {
    Row(gap: 8, align: .center) {
      Icon(name: .mail, size: .row)
      TextCaption(text: copy.sim, width: .fill)
      TextCaption(value: note.as_of)
    }
    TextTitle(text: note.title, width: .fill)
    TextCaption(value: note.status)
    when mode == .brief {
      TextBody(text: note.subtitle, width: .fill)
      TextBody(text: note.summary, width: .fill)
      TextBody(text: copy.gist, width: .fill)
      Chip(text: copy.b_code, on_tap: show_code, tone: .primary)
      Chip(text: copy.b_details, on_tap: show_pickup, tone: .normal)
      TextBody(text: copy.next, width: .fill)
    }
    when mode == .code {
      TextBody(text: note.metric1_label, width: .fill)
      TextTitle(text: note.metric1_value, width: .fill)
      TextBody(text: note.pick3_title, width: .fill)
      TextBody(text: note.pick3_body, width: .fill)
      Chip(text: copy.b_back, on_tap: back, tone: .normal)
    }
    when mode == .pickup {
      TextBody(text: note.pick1_title, width: .fill)
      TextBody(text: note.pick1_body, width: .fill)
      TextBody(text: note.pick2_title, width: .fill)
      TextBody(text: note.pick2_body, width: .fill)
      TextBody(text: note.metric2_label, width: .fill)
      TextBody(text: note.metric2_value, width: .fill)
      Chip(text: copy.b_back, on_tap: back, tone: .normal)
    }
  }
}
